const body = $json.body || $json.query || $json;

const clean = (v) => String(v ?? '').trim();

const trade = clean(body.trade);
const city = clean(body.city);
const state = clean(body.state).toUpperCase();
const zip = clean(body.zip_code || body.zip).replace(/\D/g, '').slice(0, 5);
const wo = clean(body.wo_number);

if (!trade) throw new Error('trade is required');
if (!city && !zip) throw new Error('city or zip_code is required');

return [{
  json: {
    wo_number: wo,
    trade,
    city,
    state,
    zip_code: zip,
    nearby_radius_miles: 25,
    max_adjacent_cities: 12
  }
}];

const ctx = $('Normalize Live Search').first().json;
const r = $input.first().json;
const base = Array.isArray(r) ? r[0] : r;

if (!base?.lat || !base?.lon) {
  throw new Error(`Could not locate base city: ${ctx.city}, ${ctx.state}`);
}

const radiusMeters = Math.round(Number(ctx.nearby_radius_miles || 25) * 1609.344);

const data = `[out:json][timeout:25];
(
  node["place"~"city|town|village"](around:${radiusMeters},${Number(base.lat)},${Number(base.lon)});
  way["place"~"city|town|village"](around:${radiusMeters},${Number(base.lat)},${Number(base.lon)});
  relation["place"~"city|town|village"](around:${radiusMeters},${Number(base.lat)},${Number(base.lon)});
);
out center tags;`;

return [{ json: { ...ctx, base_lat: Number(base.lat), base_lon: Number(base.lon), overpass_query: data } }];

const ctx = $('Normalize Live Search').first().json;
const baseInfo = $('Build Nearby City Query').first().json;
const nearbyResponse = $input.first().json;

const trade = String(ctx.trade || '').trim();
const baseCity = String(ctx.city || '').trim();
const baseState = String(ctx.state || '').trim().toUpperCase();
const zip = String(ctx.zip_code || '').replace(/\D/g,'').slice(0,5);
const wo = String(ctx.wo_number || '').trim();

const baseLat = Number(baseInfo.base_lat);
const baseLon = Number(baseInfo.base_lon);
const maxAdjacent = Number(ctx.max_adjacent_cities || 12);
const maxMiles = Number(ctx.nearby_radius_miles || 25);

function clean(v){ return String(v || '').trim().replace(/\s+/g,' '); }
function rad(v){ return v * Math.PI / 180; }
function miles(lat1,lon1,lat2,lon2){
  const R=3958.7613, dLat=rad(lat2-lat1), dLon=rad(lon2-lon1);
  const a=Math.sin(dLat/2)**2 + Math.cos(rad(lat1))*Math.cos(rad(lat2))*Math.sin(dLon/2)**2;
  return 2*R*Math.asin(Math.sqrt(a));
}

const cities = [{
  city: baseCity, state: baseState, zip_code: zip,
  latitude: baseLat, longitude: baseLon,
  city_type: 'same_city', distance_miles: 0
}];

const elements = Array.isArray(nearbyResponse.elements) ? nearbyResponse.elements : [];
const map = new Map();

for (const el of elements) {
  const tags = el.tags || {};
  const city = clean(tags.name || tags['name:en']);
  if (!city) continue;

  const lat = Number(el.lat ?? el.center?.lat);
  const lon = Number(el.lon ?? el.center?.lon);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

  const d = miles(baseLat, baseLon, lat, lon);
  if (d > maxMiles) continue;
  if (city.toLowerCase() === baseCity.toLowerCase()) continue;

  let state = clean(tags['addr:state'] || tags['is_in:state_code'] || baseState).toUpperCase();
  if (state.length !== 2) state = baseState;

  const key = city.toLowerCase() + '|' + state;
  const row = {city,state,latitude:lat,longitude:lon,city_type:'adjacent_city',distance_miles:Math.round(d*10)/10};
  if (!map.has(key) || row.distance_miles < map.get(key).distance_miles) map.set(key,row);
}

cities.push(...[...map.values()].sort((a,b)=>a.distance_miles-b.distance_miles).slice(0,maxAdjacent));

const templates = [
  {platform:'general', build:loc => `${trade} ${loc}`},
  {platform:'service', build:loc => `${trade} contractor service repair ${loc}`},
  {platform:'facebook', build:loc => `site:facebook.com ${trade} ${loc}`},
  {platform:'directories', build:loc => `${trade} ${loc} (site:yelp.com OR site:thumbtack.com OR site:angi.com OR site:homeadvisor.com)`}
];

const searchedCities = cities.map(c => ({
  city:c.city,state:c.state,type:c.city_type,distance_miles:c.distance_miles
}));

const output = [];
for (const place of cities) {
  const loc = `${place.city} ${place.state}`.trim();
  for (const t of templates) {
    output.push({json:{
      wo_number:wo, trade,
      base_city:baseCity, base_state:baseState, base_zip_code:zip,
      city:place.city, state:place.state,
      search_city:place.city, search_state:place.state,
      city_type:place.city_type, distance_miles:place.distance_miles,
      platform:t.platform,
      q:t.build(loc).replace(/\s+/g,' ').trim(),
      search_meta:{
        execution_mode:'single_n8n_execution',
        cities_count:cities.length,
        queries_count:cities.length*templates.length,
        searched_cities:searchedCities
      }
    }});
  }
}
return output;

const ctx = $('Build Queries').item.json;
const resp = $json || {};
return { json: { ...ctx, organic: Array.isArray(resp.organic) ? resp.organic : [] } };

const all = $input.all();
const first = all[0]?.json || {};

const trade = String(first.trade || '').trim();
const baseCity = String(first.base_city || first.city || '').trim();
const baseState = String(first.base_state || first.state || '').trim();
const zip = String(first.base_zip_code || first.zip_code || '').trim();
const wo = String(first.wo_number || '').trim();
const meta = first.search_meta || {};

function norm(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9+ ]/g,' ').replace(/\s+/g,' ').trim(); }

const aliasMap = {
  'hvac': ['hvac','heating','cooling','air conditioning','air conditioner','ac repair','furnace'],
  'plumbing': ['plumbing','plumber','drain','sewer','pipe','toilet','faucet'],
  'plumber': ['plumbing','plumber','drain','sewer','pipe','toilet','faucet'],
  'electrical': ['electrical','electrician','electric','wiring','breaker','outlet'],
  'electrician': ['electrical','electrician','electric','wiring','breaker','outlet'],
  'handyman': ['handyman','maintenance','repair','general contractor'],
  'locksmith': ['locksmith','lock','key','door hardware'],
  'appliance': ['appliance','refrigerator','washer','dryer','oven','dishwasher'],
  'glass repair': ['glass','window','storefront','glazier'],
  'landscaping': ['landscaping','landscape','lawn','yard'],
  'snow removal': ['snow removal','snow plow','plowing'],
  'junk removal': ['junk removal','hauling','debris removal'],
  'power wash': ['power wash','pressure wash','pressure washing']
};

const tkey = norm(trade);
const aliases = aliasMap[tkey] || [tkey];

function tradeMatches(text){
  const x = norm(text);
  return aliases.some(a => x.includes(norm(a)));
}

function normalizePhone(p){
  let d=String(p||'').replace(/\D/g,'');
  if(d.length===11&&d[0]==='1') d=d.slice(1);
  return d.length===10?d:'';
}
function findPhone(t){
  const m=String(t||'').match(/(?:\+?1[\s.\-]?)?\(?([2-9]\d{2})\)?[\s.\-]?([2-9]\d{2})[\s.\-]?(\d{4})/);
  return m ? normalizePhone(m[0]) : '';
}
function detectPlatform(link){
  const l=String(link||'').toLowerCase();
  if(l.includes('facebook.com/groups'))return 'facebook_group';
  if(l.includes('facebook.com')||l.includes('fb.com'))return 'facebook_page';
  if(l.includes('instagram.com'))return 'instagram';
  if(l.includes('craigslist.org'))return 'craigslist';
  if(l.includes('nextdoor.com'))return 'nextdoor';
  if(l.includes('yelp.com'))return 'yelp';
  if(l.includes('thumbtack.com'))return 'thumbtack';
  if(l.includes('angi.com')||l.includes('angieslist.com'))return 'angi';
  if(l.includes('homeadvisor.com'))return 'homeadvisor';
  if(l.includes('bbb.org'))return 'bbb';
  if(l.includes('google.com/maps'))return 'google_maps';
  return 'website';
}
function soloScore(t,s){
  const x=norm(`${t} ${s}`); let sc=30;
  const plus=[[/\bcall me\b/,20],[/\btext me\b/,20],[/\bdm me\b/,18],[/\bindependent\b|\bfreelance\b/,20],[/\bowner operator\b|\bowner operated\b/,20],[/\bself employed\b/,15],[/\bcontractor\b/,10],[/\btechnician\b|\btech\b/,10],[/\brepair\b|\bservice\b/,6],[/\bfamily owned\b|\blocal\b/,8]];
  const minus=[[/\bfranchise\b|\bnationwide\b/,-25],[/\bhiring\b|\bcareers\b/,-18]];
  for(const [p,v] of plus) if(p.test(x)) sc+=v;
  for(const [p,v] of minus) if(p.test(x)) sc+=v;
  return Math.max(0,Math.min(100,sc));
}
function pBonus(p){ return {facebook_group:15,craigslist:15,nextdoor:12,facebook_page:10,instagram:8,thumbtack:12,angi:10,homeadvisor:10,yelp:8,google_maps:10,bbb:6,website:5}[p]||3; }

const seenPhone=new Set(), seenUrl=new Set(), rows=[];
const rejected={no_link:0,no_trade_match:0,dup:0};

for(const item of all){
  const j=item.json||{};
  const organic=Array.isArray(j.organic)?j.organic:[];
  for(const r of organic){
    const title=String(r.title||'').trim();
    const snippet=String(r.snippet||'').trim();
    const link=String(r.link||'').trim();
    if(!link){rejected.no_link++;continue;}
    if(link.includes('google.com/search')) continue;

    const combined=`${title} ${snippet}`;
    if(!tradeMatches(combined)){rejected.no_trade_match++;continue;}

    const phone=findPhone(combined);
    const urlKey=link.toLowerCase().replace(/\/$/,'');
    if(seenUrl.has(urlKey)){rejected.dup++;continue;}
    if(phone && seenPhone.has(phone)){rejected.dup++;continue;}
    seenUrl.add(urlKey);
    if(phone) seenPhone.add(phone);

    const platform=detectPlatform(link);
    const solo=soloScore(title,snippet);
    let score=solo+pBonus(platform)+(phone?15:0);

    if(j.city_type==='same_city') score+=25;
    else score+=Math.max(0,15-Number(j.distance_miles||0)/2);

    rows.push({
      name:title.replace(/\s*\|\s*Facebook\s*$/i,'').replace(/\s*\|\s*Instagram\s*$/i,'').trim(),
      phone,
      phone_normalized:phone,
      phone_display:phone?`(${phone.slice(0,3)}) ${phone.slice(3,6)}-${phone.slice(6)}`:'',
      source_url:link,
      facebook_url:platform.startsWith('facebook')?link:'',
      platform,
      snippet,
      solo_score:solo,
      has_phone:!!phone,
      rank_score:Math.round(score*10)/10,
      trade,
      city:j.search_city||j.city||'',
      state:j.search_state||j.state||'',
      city_type:j.city_type||'adjacent_city',
      distance_miles:Number(j.distance_miles||0),
      zip_code:zip,
      wo_number:wo
    });
  }
}

rows.sort((a,b)=>{
  const ca=a.city_type==='same_city'?0:1, cb=b.city_type==='same_city'?0:1;
  if(ca!==cb) return ca-cb;
  if(a.distance_miles!==b.distance_miles) return a.distance_miles-b.distance_miles;
  return b.rank_score-a.rank_score;
});

return [{json:{
  ok:rows.length>0,
  count:rows.length,
  wo_number:wo,
  trade,
  city:baseCity,
  state:baseState,
  zip_code:zip,
  total_passed:rows.length,
  rejected_summary:rejected,
  searched_cities:meta.searched_cities||[],
  cities_count:meta.cities_count||0,
  queries_count:meta.queries_count||0,
  message:rows.length?null:`No matching ${trade} results were found in the base or adjacent cities.`,
  candidates:rows
}}];
